class AutoTuningPool {
    constructor(name, options = {}) {
        this.name = name;
        this.minConcurrency = options.min || 1;
        this.maxConcurrency = options.max || 32;
        this.concurrency = options.initial || 4;
        this.active = 0;
        this.queue = [];

        // AIMD parameters
        this.increaseStep = options.increaseStep || 1;
        this.decreaseFactor = options.decreaseFactor || 0.5;
        this.tuneIntervalMs = options.tuneIntervalMs || 5000;
        this.latencyTargetMs = options.latencyTargetMs || 200;

        // Metrics window
        this._window = [];
        this._windowSizeMs = 10000;
        this._tuner = setInterval(() => this._tune(), this.tuneIntervalMs);

        // Totals
        this.totalProcessed = 0;
        this.totalErrors = 0;
    }

    async execute(fn) {
        if (this.active >= this.concurrency) {
            // Queue the request
            await new Promise((resolve) => this.queue.push(resolve));
        }

        this.active++;
        const start = Date.now();

if (this.state === "OPEN") {
            this.emit("rejected", { name: this.name, state: this.state });
            throw new Error(`Circuit breaker [${this.name}] is OPEN — request rejected`);
        }

        try {
            const result = await fn();
            this._onSuccess();
            return result;
        } catch (err) {
            this._onFailure(err);
            throw err;
        }
    }

    _onSuccess() {
        this.successes++;
        this.totalSuccesses++;

        if (this.state === "HALF_OPEN") {
            this.halfOpenAttempts++;
            if (this.halfOpenAttempts >= this.halfOpenMaxAttempts) {
                this._transition("CLOSED");
                this.failures = 0;
                this.halfOpenAttempts = 0;
            }
        } else {
            this.failures = Math.max(0, this.failures - 1); // Decay on success
        }
    }

    _onFailure(err) {
        this.failures++;
        this.totalFailures++;
        this.lastFailureTime = Date.now();

        if (this.state === "HALF_OPEN") {
            this._transition("OPEN");
            this.halfOpenAttempts = 0;
        } else if (this.failures >= this.failureThreshold) {
            this._transition("OPEN");
        }

        this.emit("failure", { name: this.name, error: err.message, failures: this.failures });
    }

